function check([aliceSizes, bobSizes], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== 2) return false;
  const [give, take] = actual;
  if (!aliceSizes.includes(give) || !bobSizes.includes(take)) return false;
  const aliceTotal = aliceSizes.reduce((sum, v) => sum + v, 0);
  const bobTotal = bobSizes.reduce((sum, v) => sum + v, 0);
  return aliceTotal - give + take === bobTotal - take + give;
}

