function validate([aliceSizes, bobSizes]) {
  if (!Array.isArray(aliceSizes) || aliceSizes.length < 1 || aliceSizes.length > 10000) return 'aliceSizes needs 1 to 10000 boxes.';
  if (!Array.isArray(bobSizes) || bobSizes.length < 1 || bobSizes.length > 10000) return 'bobSizes needs 1 to 10000 boxes.';
  const bad = v => !Number.isInteger(v) || v < 1 || v > 100000;
  if (aliceSizes.some(bad) || bobSizes.some(bad)) return 'Each box size is an integer from 1 to 100000.';
  const aliceTotal = aliceSizes.reduce((sum, v) => sum + v, 0);
  const bobTotal = bobSizes.reduce((sum, v) => sum + v, 0);
  if (aliceTotal === bobTotal) return 'Alice and Bob must start with different totals.';
  const bobBoxes = new Set(bobSizes);
  const delta = (bobTotal - aliceTotal) / 2;
  if (!aliceSizes.some(v => bobBoxes.has(v + delta))) return 'There must be at least one fair trade.';
  return null;
}

