function fairCandySwap(aliceSizes, bobSizes) {
  let aliceTotal = 0;
  for (const size of aliceSizes) {
    aliceTotal += size;
  }
  let bobTotal = 0;
  for (const size of bobSizes) {
    bobTotal += size;
  }
  const delta = (bobTotal - aliceTotal) / 2;
  const bobBoxes = new Set(bobSizes);

  for (const give of aliceSizes) {
    const take = give + delta;
    if (bobBoxes.has(take)) {
      return [give, take];
    }
  }
  return [];
}

