  for (let i = 0; i < aliceSizes.length; i++) {
    for (let j = 0; j < bobSizes.length; j++) {
      const alice = aliceSizes.slice();
      const bob = bobSizes.slice();
      [alice[i], bob[j]] = [bob[j], alice[i]];
      if (total(alice) === total(bob)) return [aliceSizes[i], bobSizes[j]];
    }
  }
  return [];
}

