function generate(rand, size) {
  const large = size === 'large';
  const maxV = large ? 100000 : 9;
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  for (;;) {
    const n = large ? int(1200, 2000) : int(1, 6);
    const m = large ? Math.max(1, n + int(-60, 60)) : int(1, 6);
    const alice = Array.from({ length: n }, () => int(1, maxV));
    const bob = Array.from({ length: m }, () => int(1, maxV));
    // Choose the trade first, then nudge the other boxes until the totals fit it.
    const i = int(0, n - 1);
    const j = int(0, m - 1);
    if (alice[i] === bob[j]) continue;
    let excess = alice.reduce((s, v) => s + v, 0) - bob.reduce((s, v) => s + v, 0) - 2 * (alice[i] - bob[j]);
    for (let k = 0; k < n && excess !== 0; k++) {
      if (k === i) continue;
      const next = Math.min(maxV, Math.max(1, alice[k] - excess));
      excess += next - alice[k];
      alice[k] = next;
    }
    for (let k = 0; k < m && excess !== 0; k++) {
      if (k === j) continue;
      const next = Math.min(maxV, Math.max(1, bob[k] + excess));
      excess -= next - bob[k];
      bob[k] = next;
    }
    if (excess === 0) return [alice, bob];
  }
}
